                                   deviceProp.get_global_mem_cache_size(),
                                   dpct::get_in_order_queue())));

    cudaCheck(DPCT_CHECK_ERROR(start = new sycl::event()));
    cudaCheck(DPCT_CHECK_ERROR(stop = new sycl::event()));
